    if (!env || !goals || goal_count == 0U || !cb) { return 0U; }

    /* Static to keep these large structures off the call stack.
     * solve() is non-reentrant by design. */
    static GoalStack   gs;
    static ChoiceStack cs;
    memset(&gs, 0, sizeof(GoalStack));
    memset(&cs, 0, sizeof(ChoiceStack));

