/*
 * Temporary per-bucket accumulator used during index construction.
 * Clauses for the same first-arg key may be interleaved with clauses for
 * other keys, so we cannot build the flat slot array in a single forward
 * pass.  We accumulate per-bucket lists first, then lay them out
 * contiguously in idx_clause_slots[].
 */
struct BucketTemp {
    uint32_t slots[INDEX_MAX_INDEXED];
    uint32_t count = 0U;
};

void db_build_index(PredEntry *pred, const Database *db, const TermArena *arena)
{
    assert(pred != nullptr && db != nullptr && arena != nullptr);

    FirstArgIndex *idx = &pred->index;
    memset(idx, 0, sizeof(FirstArgIndex));

    if (pred->arity == 0U || pred->count == 0U) {
        idx->built = true;
        return;
    }

    /* Temporary per-bucket slot accumulators (static: large but non-reentrant) */
    static BucketTemp tmp[INDEX_MAX_BUCKETS];
    for (uint32_t i = 0U; i < INDEX_MAX_BUCKETS; ++i) { tmp[i].count = 0U; }

    /* Pass 1: classify each clause into a bucket or the var catch-all */
    for (uint32_t ci = 0U; ci < pred->count; ++ci) {
        const uint32_t abs_pos = pred->first + ci;
        const StoredClause *sc = db_get_clause(db, abs_pos);
        if (sc == nullptr) { continue; }

        const Term *head = term_get(arena, sc->head);
        if (head == nullptr) { continue; }

        TermRef first_arg_ref = TERM_REF_INVALID;
        if (head->kind == TERM_KIND_COMPOUND && head->data.compound.arity >= 1U) {
            first_arg_ref = term_arg(arena, sc->head, 0U);
        }

        const Term *fa = (first_arg_ref != TERM_REF_INVALID)
                         ? term_get(arena, first_arg_ref) : nullptr;

        bool         is_ground = false;
        IndexKeyKind kind      = INDEX_KEY_ATOM;
        IndexKey     key       = {};

        if (fa != nullptr) {
            if (fa->kind == TERM_KIND_ATOM) {
                is_ground   = true;
                kind        = INDEX_KEY_ATOM;
                key.atom_id = fa->data.atom_id;
            } else if (fa->kind == TERM_KIND_INT) {
                is_ground   = true;
                kind        = INDEX_KEY_INT;
                key.int_val = fa->data.int_val;
            }
        }

        if (!is_ground) {
            if (idx->idx_var_count < INDEX_MAX_VAR_CLAUSES) {
                idx->idx_var_slots[idx->idx_var_count++] = abs_pos;
            }
            continue;
        }

        /* Find or create bucket */
        uint32_t bucket = INDEX_MAX_BUCKETS;
        for (uint32_t bi = 0U; bi < idx->idx_bucket_count; ++bi) {
            if (idx->idx_kind[bi] != kind) { continue; }
            if (kind == INDEX_KEY_ATOM && idx->idx_key[bi].atom_id == key.atom_id) {
                bucket = bi; break;
            }
            if (kind == INDEX_KEY_INT  && idx->idx_key[bi].int_val == key.int_val) {
                bucket = bi; break;
            }
        }

        if (bucket == INDEX_MAX_BUCKETS) {
            if (idx->idx_bucket_count >= INDEX_MAX_BUCKETS) {
                /* Overflow: treat as var clause */
                if (idx->idx_var_count < INDEX_MAX_VAR_CLAUSES) {
                    idx->idx_var_slots[idx->idx_var_count++] = abs_pos;
                }
                continue;
            }
            bucket = idx->idx_bucket_count;
            idx->idx_kind[bucket] = kind;
            idx->idx_key[bucket]  = key;
            idx->idx_bucket_count++;
        }

        if (tmp[bucket].count < INDEX_MAX_INDEXED) {
            tmp[bucket].slots[tmp[bucket].count++] = abs_pos;
        }
    }

    /* Pass 2: lay out buckets contiguously in idx_clause_slots[] */
    for (uint32_t bi = 0U; bi < idx->idx_bucket_count; ++bi) {
        idx->idx_start[bi] = idx->idx_slot_count;
        idx->idx_count[bi] = tmp[bi].count;
        for (uint32_t si = 0U; si < tmp[bi].count; ++si) {
            if (idx->idx_slot_count < INDEX_MAX_INDEXED) {
                idx->idx_clause_slots[idx->idx_slot_count++] = tmp[bi].slots[si];
            }
        }
    }

    idx->built = true;
}

